{
    "id": "vuln-notesnook-e87f5e5f",
    "message": "Potential XSS vulnerability in embed component. The code directly interpolates user-provided 'src' URL into HTML without proper sanitization, which could allow attackers to inject malicious scripts. The fix properly creates an anchor element and uses outerHTML to safely include the URL with the ref_src parameter. To prevent this vulnerability, always sanitize or properly encode user input before inserting it into HTML templates.",
    "severity": "ERROR",
    "languages": ["typescript"],
    "metadata": {
        "category": "security",
        "cwe": "79",
        "owasp": "OWASP_2021_A03"
    },
    "pattern_either": [
        "const $VAR = \"<p lang=\\\"en\\\" dir=\\\"ltr\\\"><a href=\\\"${...}?ref_src=twsrc%5Etfw\"></a></blockquote>\"",
        "\"<p lang=\\\"en\\\" dir=\\\"ltr\\\"><a href=\\\"${...}?ref_src=twsrc%5Etfw\"></a></blockquote>\"",
        "const $VAR = `<p lang=\"en\" dir=\"ltr\"><a href=\"${...}?ref_src=twsrc%5Etfw\"></a></blockquote>`"
    ],
    "pattern_not": [
        "anchor.outerHTML",
        "document.createElement(\"a\")"
    ]
}

